/// <reference types="vitest/globals" />

// ประกาศ global ของ vitest (`test`, `expect`, `describe`, `beforeEach`, `vi`)
// ให้ TypeScript รู้จัก
//
// **ทำไมต้องมีไฟล์นี้**
//
// `vitest.config.ts` ตั้ง `globals: true` ซึ่งทำให้ตัวรันเทสต์ฉีดฟังก์ชันเหล่านี้
// เข้า global scope ตอนรันจริง แต่ **`tsc` ไม่ได้อ่าน `vitest.config.ts`**
// มันจึงไม่รู้จักชื่อพวกนั้นเลย ผลคือ `npx tsc --noEmit` รายงาน error ราว 500 ตัว
// ในไฟล์ `*.test.ts` ทั้งหมด และ **exit ด้วยรหัส 2 ทุกครั้ง**
//
// ที่ผ่านมาแก้ด้วยการกรองข้อความ (`| grep -v "\.test\.ts"`) ซึ่งซ่อนแค่บรรทัด
// ที่แสดง ไม่ได้เปลี่ยน exit code — เทอร์มินัลจึงขึ้นสัญลักษณ์ล้มเหลวทุกครั้ง
// **สัญญาณล้มเหลวที่เกิดขึ้นทุกครั้งโดยไม่มีอะไรผิดจริง สอนให้คนเลิกอ่านมัน**
// วันที่มี error จริงนอกไฟล์เทสต์จะแยกไม่ออกจากเสียงรบกวนประจำ
// (หลักการเดียวกับ `tolerateOutage` ในชุดเทสต์ และการปิด cron ที่แดงทุกคืน)
//
// **ทำไมใช้ไฟล์ .d.ts แทนการเติม `types` ใน tsconfig**
//
// การใส่ `"types": [...]` ใน `compilerOptions` **จำกัด** แพ็กเกจ `@types/*`
// ที่ถูกดึงเข้ามาอัตโนมัติให้เหลือเฉพาะที่ระบุ — ลืมใส่ `node` เมื่อไร สคริปต์ใน
// `scripts/` ที่ใช้ `process` กับ `Buffer` จะพังทันที การอ้างผ่าน triple-slash
// เป็นการ **เพิ่ม** โดยไม่แตะการดึงอัตโนมัติของตัวอื่นเลย จึงไม่มีผลข้างเคียง
//
// ไฟล์นี้ถูกรวมโดย `include: ["**/*.ts"]` ใน tsconfig อยู่แล้ว ไม่ต้องตั้งค่าเพิ่ม
export {}
